mapper.select:
SELECT DISTINCT bmae.id, bmae.score, bmat.handle_uid from bbx_meeting_attendant_evaluate bmae LEFT JOIN bbx_meeting_attendant_task bmat ON bmat.reserve_id = bmae.reserve_id
AND bmat.tenant_id =#{condition.tenantId}
AND (#{condition.endTime} >= bmae.create_time and #{condition.startTime} <= bmat.create_time)
AND bmat.handle_uid in
#{userId}
AND bmat.service_status = 3 AND bmat.handle_uid is not null

SELECT DISTINCT bmae.id, bmae.score, bmae.content, bmae.operate_uid, bmae.operate_uname, bmae.operate_staffid, bmae.create_time, bmat.room_id, bmat.room_name, bmat.reserve_id, bmat.reserve_name, bmat.handle_uid, bmat.handle_uname, bmat.handle_staffid from bbx_meeting_attendant_evaluate bmae LEFT JOIN bbx_meeting_attendant_task bmat ON bmat.reserve_id = bmae.reserve_id
AND bmae.tenant_id =#{condition.tenantId}
AND (#{condition.endTime} >= bmae.create_time and #{condition.startTime} <= bmae.create_time)
AND bmat.reserve_name like concat('%',#{condition.reserveName},'%')
AND bmat.handle_uid =#{condition.userId}
AND bmat.room_id =#{condition.roomId}
AND bmat.handle_uid in
#{userId}
AND bmat.service_status = 3 AND bmat.handle_uid is not null
order by
bmae.score ${condition.sortOrder},
bmae.create_time DESC

SELECT
staffId,
ROUND(SUM(score) / COUNT(1), 1) AS avgScore
FROM (
SELECT DISTINCT t.handle_uid AS staffId, e.id, e.score
FROM bbx_meeting_attendant_task t
INNER JOIN bbx_meeting_attendant_evaluate e
ON t.reserve_id = e.reserve_id
WHERE t.service_status = 3

    AND t.tenant_id =#{tenantId}


    AND e.tenant_id =#{tenantId}


    AND (#{endTime} >= e.create_time and #{startTime} <= e.create_time)


    AND t.handle_uid in

        #{userId}


) tmp
GROUP BY staffId;
